#pragma once

#include "core/error.h"
#include "core/theory/weekdayplan.h"

#include <array>
#include <filesystem>
#include <map>
#include <string>
#include <vector>

// routines/default.json (routine-spec.md section 7, routine.md section 4): modules, their modes and option value
// lists, and the weekday plan. Values are data; voicings and orders are generated by core/theory.
namespace cc::routine
{

struct ModeDefinition { // NOLINT(bugprone-exception-escape) plain aggregate; string members may allocate
    std::string id;
    std::string name;
    std::map<std::string, std::vector<std::string>> options; // option name -> allowed values, first = default
};

struct ModuleDefinition { // NOLINT(bugprone-exception-escape) plain aggregate; string members may allocate
    std::string id; // "01".."04", same as the stats event module field
    std::string name;
    int defaultMinutes = 10;
    std::vector<ModeDefinition> modes; // empty while a module is on hold
};

struct RoutineDefinition {
    int schemaVersion = 1;
    std::vector<ModuleDefinition> modules;
    std::array<theory::WeekdayPlan, 7> weekdayPlan{}; // index = theory::Weekday
};

constexpr int routineSchemaVersion = 1;

/// Parses and validates the file: ids "01".."04", non-empty option lists, modes 1..7, key names. Keys "auto"
/// resolve to theory::defaultWeekdayPlan.
Result<RoutineDefinition> loadRoutineDefinition(const std::filesystem::path &path);

/// The compiled-in fallback used when the file is missing or broken (routine.md section 7): same content as
/// data/routines/default.json.
RoutineDefinition builtInRoutineDefinition();

} // namespace cc::routine
